import { Preferences } from '@capacitor/preferences';

async function refreshList(): Promise<void> {
  const list = document.getElementById('kv-list');
  if (!list) return;
  // Clear existing children
  while (list.firstChild) {
    list.removeChild(list.firstChild);
  }

  const { keys } = await Preferences.keys();
  for (const key of keys) {
    const { value } = await Preferences.get({ key });
    const li = document.createElement('li');
    li.setAttribute('data-key', key);
    li.textContent = `${key}=${value ?? ''}`;
    list.appendChild(li);
  }
}

function getInput(id: string): HTMLInputElement | null {
  return document.getElementById(id) as HTMLInputElement | null;
}

async function handleSet(): Promise<void> {
  const keyInput = getInput('kv-key');
  const valueInput = getInput('kv-value');
  if (!keyInput || !valueInput) return;
  const key = keyInput.value;
  const value = valueInput.value;
  if (!key) return;
  await Preferences.set({ key, value });
  await refreshList();
}

async function handleRemove(): Promise<void> {
  const keyInput = getInput('kv-key');
  if (!keyInput) return;
  const key = keyInput.value;
  if (!key) return;
  await Preferences.remove({ key });
  await refreshList();
}

async function handleClear(): Promise<void> {
  await Preferences.clear();
  await refreshList();
}

function setup(): void {
  const setBtn = document.getElementById('kv-set-btn');
  const removeBtn = document.getElementById('kv-remove-btn');
  const clearBtn = document.getElementById('kv-clear-btn');

  setBtn?.addEventListener('click', () => {
    void handleSet();
  });
  removeBtn?.addEventListener('click', () => {
    void handleRemove();
  });
  clearBtn?.addEventListener('click', () => {
    void handleClear();
  });

  void refreshList();
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', setup);
} else {
  setup();
}
EOF

